# 11-felsefe-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Bir Argümanın İskeleti: Öncüllerden Sonuca</text><rect x="30" y="52" width="330" height="48" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/><text x="45" y="72" font-size="12" font-weight="bold" fill="#075985">Öncül 1</text><text x="45" y="90" font-size="12" fill="#0c4a6e">Var olmaya başlayan her şeyin bir nedeni vardır.</text><rect x="30" y="110" width="330" height="48" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/><text x="45" y="130" font-size="12" font-weight="bold" fill="#075985">Öncül 2</text><text x="45" y="148" font-size="12" fill="#0c4a6e">Evren var olmaya başlamıştır.</text><rect x="30" y="168" width="330" height="48" rx="10" fill="#fef9c3" stroke="#ca8a04" stroke-width="2" stroke-dasharray="6 4"/><text x="45" y="188" font-size="12" font-weight="bold" fill="#854d0e">Örtük öncül (açığa çıkarılmalı)</text><text x="45" y="206" font-size="12" fill="#713f12">Nedenler zinciri sonsuza kadar geriye gidemez.</text><line x1="365" y1="134" x2="420" y2="134" stroke="#334155" stroke-width="3"/><polygon points="420,126 436,134 420,142" fill="#334155"/><rect x="442" y="98" width="290" height="72" rx="12" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="587" y="124" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">SONUÇ</text><text x="587" y="148" text-anchor="middle" font-size="12" fill="#14532d">Evrenin var olmasının bir nedeni vardır.</text><rect x="30" y="232" width="340" height="52" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/><text x="200" y="254" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">Geçerlilik sorusu</text><text x="200" y="272" text-anchor="middle" font-size="11" fill="#4c1d95">Öncüller doğruysa sonuç zorunlu olarak çıkar mı?</text><rect x="390" y="232" width="342" height="52" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="561" y="254" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Sağlamlık sorusu</text><text x="561" y="272" text-anchor="middle" font-size="11" fill="#7f1d1d">Geçerli mi ve öncüllerin her biri gerçekten doğru mu?</text></svg>', 'b2': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Ontolojik Argüman: İddia ve İki Büyük İtiraz</text><rect x="25" y="55" width="225" height="220" rx="12" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/><text x="137" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#075985">ANSELMUS</text><text x="137" y="98" text-anchor="middle" font-size="11" fill="#0369a1">(11. yüzyıl)</text><text x="40" y="126" font-size="11" fill="#0c4a6e">1. Tanrı: daha büyüğü</text><text x="52" y="142" font-size="11" fill="#0c4a6e">düşünülemeyen varlık</text><text x="40" y="166" font-size="11" fill="#0c4a6e">2. Bu kavram zihinde var</text><text x="40" y="190" font-size="11" fill="#0c4a6e">3. Gerçekte var olmak</text><text x="52" y="206" font-size="11" fill="#0c4a6e">daha büyüktür</text><text x="40" y="236" font-size="12" font-weight="bold" fill="#075985">Sonuç: Tanrı gerçekte</text><text x="40" y="254" font-size="12" font-weight="bold" fill="#075985">de vardır.</text><polygon points="255,155 275,165 255,175" fill="#475569"/><rect x="280" y="55" width="215" height="220" rx="12" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="387" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">GAUNILO</text><text x="387" y="98" text-anchor="middle" font-size="11" fill="#b45309">Biçime itiraz</text><text x="295" y="126" font-size="11" fill="#78350f">En kusursuz ada düşünülür.</text><text x="295" y="150" font-size="11" fill="#78350f">Aynı biçim uygulanırsa</text><text x="295" y="166" font-size="11" fill="#78350f">ada da var olmalıdır.</text><text x="295" y="196" font-size="12" font-weight="bold" fill="#92400e">Saçma sonuç, öyleyse</text><text x="295" y="214" font-size="12" font-weight="bold" fill="#92400e">biçim kusurludur.</text><text x="295" y="246" font-size="10" fill="#78350f">Yanıt: Ada olumsaldır,</text><text x="295" y="260" font-size="10" fill="#78350f">Tanrı zorunlu varlıktır.</text><polygon points="500,155 520,165 500,175" fill="#475569"/><rect x="525" y="55" width="210" height="220" rx="12" fill="#fce7f3" stroke="#db2777" stroke-width="2"/><text x="630" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#9d174d">KANT</text><text x="630" y="98" text-anchor="middle" font-size="11" fill="#be185d">3. öncüle itiraz</text><text x="540" y="126" font-size="11" fill="#831843">Varlık gerçek bir</text><text x="540" y="142" font-size="11" fill="#831843">yüklem değildir.</text><text x="540" y="170" font-size="11" fill="#831843">Düşünülen 100 taler =</text><text x="540" y="186" font-size="11" fill="#831843">gerçek 100 taler (kavramca)</text><text x="540" y="220" font-size="12" font-weight="bold" fill="#9d174d">Var olup olmadığı</text><text x="540" y="238" font-size="12" font-weight="bold" fill="#9d174d">deneyimle bilinir.</text></svg>', 'b3': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Kozmolojik ve Teleolojik Argümanlar: İtiraz ve Yanıt</text><rect x="25" y="50" width="345" height="235" rx="12" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/><text x="197" y="74" text-anchor="middle" font-size="14" font-weight="bold" fill="#075985">KOZMOLOJİK ARGÜMAN</text><rect x="40" y="86" width="315" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="52" y="106" font-size="11" font-weight="bold" fill="#991b1b">İtiraz (Russell):</text><text x="52" y="124" font-size="11" fill="#7f1d1d">Her insanın annesi var, türün annesi yok.</text><text x="52" y="138" font-size="10" fill="#7f1d1d">Bileşim safsatası suçlaması</text><rect x="40" y="150" width="315" height="56" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="52" y="170" font-size="11" font-weight="bold" fill="#166534">Yanıt (Copleston, İbn Sînâ çizgisi):</text><text x="52" y="188" font-size="11" fill="#14532d">Mümkünlerin toplamı da dayanağa muhtaç.</text><text x="52" y="202" font-size="10" fill="#14532d">Zorunlu Varlık gerekir</text><rect x="40" y="214" width="315" height="58" rx="8" fill="#fef9c3" stroke="#ca8a04"/><text x="52" y="234" font-size="11" font-weight="bold" fill="#854d0e">Düğüm noktası:</text><text x="52" y="252" font-size="11" fill="#713f12">Her şeyin yeterli bir açıklaması</text><text x="52" y="266" font-size="11" fill="#713f12">olmak zorunda mı?</text><rect x="390" y="50" width="345" height="235" rx="12" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/><text x="562" y="74" text-anchor="middle" font-size="14" font-weight="bold" fill="#6b21a8">TELEOLOJİK ARGÜMAN</text><rect x="405" y="86" width="315" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="417" y="106" font-size="11" font-weight="bold" fill="#991b1b">İtiraz (Hume):</text><text x="417" y="124" font-size="11" fill="#7f1d1d">Evren saate değil organizmaya da benzer.</text><text x="417" y="138" font-size="10" fill="#7f1d1d">Sonlu etkiden sonsuz neden çıkmaz</text><rect x="405" y="150" width="315" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="417" y="170" font-size="11" font-weight="bold" fill="#991b1b">İtiraz (Darwin, 1859):</text><text x="417" y="188" font-size="11" fill="#7f1d1d">Doğal seçilim uyumu tasarımcısız açıklar.</text><rect x="405" y="214" width="315" height="58" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="417" y="234" font-size="11" font-weight="bold" fill="#166534">Yeni biçim: İnce ayar argümanı</text><text x="417" y="252" font-size="11" fill="#14532d">Fizik sabitleri yaşama elverişli dar aralıkta.</text><text x="417" y="266" font-size="10" fill="#14532d">Karşı görüş: çoklu evren varsayımı</text></svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Pascal\'ın Bahsi: Karar Tablosu ve İtirazlar</text><rect x="150" y="50" width="170" height="40" rx="8" fill="#e2e8f0"/><text x="235" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e293b">Tanrı varsa</text><rect x="328" y="50" width="170" height="40" rx="8" fill="#e2e8f0"/><text x="413" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e293b">Tanrı yoksa</text><rect x="25" y="98" width="118" height="80" rx="8" fill="#e0f2fe"/><text x="84" y="143" text-anchor="middle" font-size="13" font-weight="bold" fill="#075985">İnanırsan</text><rect x="25" y="186" width="118" height="80" rx="8" fill="#e0f2fe"/><text x="84" y="231" text-anchor="middle" font-size="13" font-weight="bold" fill="#075985">İnanmazsan</text><rect x="150" y="98" width="170" height="80" rx="8" fill="#bbf7d0" stroke="#16a34a" stroke-width="2"/><text x="235" y="135" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Sonsuz kazanç</text><text x="235" y="155" text-anchor="middle" font-size="11" fill="#14532d">(ebedî mutluluk)</text><rect x="328" y="98" width="170" height="80" rx="8" fill="#fef9c3" stroke="#ca8a04" stroke-width="2"/><text x="413" y="135" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">Sınırlı kayıp</text><text x="413" y="155" text-anchor="middle" font-size="11" fill="#713f12">(dünyevi bazı hazlar)</text><rect x="150" y="186" width="170" height="80" rx="8" fill="#fecaca" stroke="#dc2626" stroke-width="2"/><text x="235" y="223" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Sonsuz kayıp</text><text x="235" y="243" text-anchor="middle" font-size="11" fill="#7f1d1d">(ebedî mutluluktan yoksunluk)</text><rect x="328" y="186" width="170" height="80" rx="8" fill="#fef9c3" stroke="#ca8a04" stroke-width="2"/><text x="413" y="223" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">Sınırlı kazanç</text><text x="413" y="243" text-anchor="middle" font-size="11" fill="#713f12">(dünyevi bazı hazlar)</text><rect x="520" y="50" width="215" height="216" rx="12" fill="#fce7f3" stroke="#db2777" stroke-width="2"/><text x="627" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#9d174d">Başlıca itirazlar</text><text x="534" y="102" font-size="11" fill="#831843">1. Çok tanrı itirazı:</text><text x="546" y="118" font-size="11" fill="#831843">seçenek yalnızca iki değil</text><text x="534" y="146" font-size="11" fill="#831843">2. İnanç iradeyle</text><text x="546" y="162" font-size="11" fill="#831843">seçilebilir mi?</text><text x="534" y="190" font-size="11" fill="#831843">3. Hesaba dayalı inanç</text><text x="546" y="206" font-size="11" fill="#831843">değerli olur mu?</text><text x="534" y="240" font-size="11" font-weight="bold" fill="#9d174d">Kanıt değil, pragmatik</text><text x="534" y="256" font-size="11" font-weight="bold" fill="#9d174d">bir gerekçe sunar.</text><text x="260" y="288" text-anchor="middle" font-size="11" fill="#334155">Olasılık sıfırdan büyükse beklenen değer inanmaktan yana ağır basar.</text></svg>', 'b5': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Kötülük Probleminin İki Biçimi</text><rect x="20" y="42" width="370" height="245" rx="12" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/><text x="205" y="64" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">MANTIKSAL BİÇİM: Mackie\'nin tutarsız üçlüsü</text><polygon points="205,92 95,212 315,212" fill="none" stroke="#ea580c" stroke-width="2" stroke-dasharray="6 4"/><rect x="135" y="76" width="140" height="32" rx="8" fill="#ffedd5" stroke="#ea580c"/><text x="205" y="97" text-anchor="middle" font-size="11" fill="#7c2d12">Tanrı\'nın gücü sınırsız</text><rect x="30" y="196" width="130" height="32" rx="8" fill="#ffedd5" stroke="#ea580c"/><text x="95" y="217" text-anchor="middle" font-size="11" fill="#7c2d12">Tanrı tamamen iyi</text><rect x="250" y="196" width="130" height="32" rx="8" fill="#ffedd5" stroke="#ea580c"/><text x="315" y="217" text-anchor="middle" font-size="11" fill="#7c2d12">Kötülük vardır</text><text x="205" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">Birlikte doğru</text><text x="205" y="181" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">olamaz mı?</text><rect x="35" y="240" width="340" height="38" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="205" y="257" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Yanıt: Özgür irade savunması (Plantinga)</text><text x="205" y="272" text-anchor="middle" font-size="10" fill="#14532d">Tutarlı bir olasılık göstermek yeterlidir.</text><rect x="405" y="42" width="335" height="245" rx="12" fill="#eef2ff" stroke="#4f46e5" stroke-width="2"/><text x="572" y="64" text-anchor="middle" font-size="13" font-weight="bold" fill="#3730a3">KANITSAL BİÇİM: Rowe</text><text x="420" y="92" font-size="11" fill="#312e81">Gözlem: Ormanda kimse görmeden acı</text><text x="420" y="108" font-size="11" fill="#312e81">çekerek ölen yavru geyik</text><line x1="572" y1="116" x2="572" y2="132" stroke="#4f46e5" stroke-width="2"/><polygon points="566,132 578,132 572,142" fill="#4f46e5"/><text x="420" y="160" font-size="11" fill="#312e81">Çıkarım: Amaçsız görünen acı</text><text x="420" y="176" font-size="11" fill="#312e81">muhtemelen gerçekten amaçsızdır.</text><text x="420" y="200" font-size="11" font-weight="bold" fill="#3730a3">Sonuç: Tanrı\'nın yokluğu olasıdır.</text><rect x="420" y="220" width="305" height="58" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="572" y="240" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Yanıt: Kuşkucu teizm</text><text x="572" y="256" text-anchor="middle" font-size="10" fill="#14532d">Görünmemesi yok olduğunu göstermez;</text><text x="572" y="270" text-anchor="middle" font-size="10" fill="#14532d">insan bilgisi sınırlıdır.</text></svg>', 'b6': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Tehâfüt Tartışması: Argüman ve Karşı Argüman</text><rect x="20" y="46" width="200" height="230" rx="12" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="120" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">GAZÂLÎ</text><text x="120" y="90" text-anchor="middle" font-size="11" fill="#b45309">(1058-1111)</text><text x="120" y="114" text-anchor="middle" font-size="11" fill="#78350f">Tehâfütü\'l-Felâsife</text><text x="120" y="130" text-anchor="middle" font-size="11" fill="#78350f">(yaklaşık 1095)</text><text x="35" y="160" font-size="11" fill="#78350f">Yöntem: iç eleştiri</text><text x="35" y="180" font-size="11" fill="#78350f">20 mesele tartışılır</text><text x="35" y="200" font-size="11" fill="#78350f">Ateş ve pamuk örneği:</text><text x="35" y="216" font-size="11" fill="#78350f">gözlenen yalnızca birliktelik</text><text x="35" y="248" font-size="11" font-weight="bold" fill="#92400e">Vurgu: aklın metafizikte</text><text x="35" y="264" font-size="11" font-weight="bold" fill="#92400e">sınırları vardır</text><rect x="540" y="46" width="200" height="230" rx="12" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="640" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">İBN RÜŞD</text><text x="640" y="90" text-anchor="middle" font-size="11" fill="#15803d">(1126-1198)</text><text x="640" y="114" text-anchor="middle" font-size="11" fill="#14532d">Tehâfütü\'t-Tehâfüt</text><text x="640" y="130" text-anchor="middle" font-size="11" fill="#14532d">(12. yüzyıl sonları)</text><text x="555" y="160" font-size="11" fill="#14532d">İtirazlar cedelîdir,</text><text x="555" y="176" font-size="11" fill="#14532d">burhani değildir</text><text x="555" y="200" font-size="11" fill="#14532d">Nedenselliği inkâr eden</text><text x="555" y="216" font-size="11" fill="#14532d">aklı inkâr eder</text><text x="555" y="248" font-size="11" font-weight="bold" fill="#166534">Vurgu: burhan ile vahiy</text><text x="555" y="264" font-size="11" font-weight="bold" fill="#166534">uyum içindedir</text><text x="380" y="62" text-anchor="middle" font-size="12" font-weight="bold" fill="#334155">Tartışılan başlıca meseleler</text><rect x="245" y="74" width="270" height="38" rx="10" fill="#e0f2fe" stroke="#0284c7"/><text x="380" y="98" text-anchor="middle" font-size="12" fill="#075985">Âlemin ezelîliği</text><rect x="245" y="120" width="270" height="38" rx="10" fill="#e0f2fe" stroke="#0284c7"/><text x="380" y="144" text-anchor="middle" font-size="12" fill="#075985">Tanrı\'nın tikelleri bilmesi</text><rect x="245" y="166" width="270" height="38" rx="10" fill="#e0f2fe" stroke="#0284c7"/><text x="380" y="190" text-anchor="middle" font-size="12" fill="#075985">Bedenle diriliş (cismani haşir)</text><rect x="245" y="212" width="270" height="38" rx="10" fill="#ede9fe" stroke="#7c3aed"/><text x="380" y="236" text-anchor="middle" font-size="12" fill="#5b21b6">Nedensellik ve Allah\'ın âdeti</text><polygon points="225,160 240,152 240,168" fill="#d97706"/><polygon points="535,160 520,152 520,168" fill="#16a34a"/><text x="380" y="272" text-anchor="middle" font-size="11" fill="#334155">Tartışma, sonuçlar üzerinden değil öncüller ve kavramlar üzerinden yürür.</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
